for lec in range(1,7):
 group=[c for c in concepts if c['lecture']==lec]
 for i,c in enumerate(group,1):
  c['id']=f'AN{lec}-C{i:02d}';c['origin']='Supplementary foundation' if c['term'] in supp else 'Handout topic, clarified';c['sourceIds']=sm[lec];c['referenceSection']='Related supplied handout: '+files[lec-1]+'; pages '+', '.join(map(str,c['pages']))+'. Read the page-map clarification where supplied wording is simplified.';c['firstQuestionId']=f'AN{lec}-{(i-1)*3+1:03d}'
  other=lookup[overrides[c['term']]] if c['term'] in overrides else group[i%len(group)]
  c['compareTerm']=other['term'];c['comparison']=c['term']+': '+c['definition']+' '+other['term']+': '+other['definition'];c['exampleReason']=c['note'];c['retrievalPrompt']='Define the concept, identify the evidence in the example, and distinguish it from '+other['term']+'.';c['modelAnswer']=c['definition']+' Example: '+c['example']+' Distinction: '+c['note'];c['slideRefs']=[dict(lecture=lec,slide=n) for n in c['pages']]
